<?php require '../config/database.php'; require_once '../config/auth.php'; require_role('user'); $uid=$_SESSION['user_id']; $member_id=mysqli_fetch_assoc(mysqli_query($conn,"SELECT id FROM members WHERE user_id=$uid"))['id']; if($_SERVER['REQUEST_METHOD']=='POST'){ $date=$_POST['date'];$steps=(int)$_POST['steps'];$workout=mysqli_real_escape_string($conn,$_POST['workout']);$cal=(int)$_POST['calories'];$w=(float)$_POST['weight'];$notes=mysqli_real_escape_string($conn,$_POST['notes']); mysqli_query($conn,"INSERT INTO activity_logs(member_id,log_date,steps,workout,calories_burned,weight_kg,notes) VALUES($member_id,'$date',$steps,'$workout',$cal,$w,'$notes')"); mysqli_query($conn,"UPDATE members SET weight_kg=$w, level_points=level_points+10 WHERE id=$member_id"); } $rows=mysqli_query($conn,"SELECT * FROM activity_logs WHERE member_id=$member_id ORDER BY log_date DESC"); ?>
<!DOCTYPE html><html><head><title>Activity</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="layout"><?php include '_nav.php'; ?><main class="main"><h1>Daily Activity Logs</h1><form class="form" method="post"><div class="three"><div><label>Date</label><input type="date" name="date" value="<?=date('Y-m-d')?>"></div><div><label>Steps</label><input type="number" name="steps"></div><div><label>Calories Burned</label><input type="number" name="calories"></div></div><div class="two"><div><label>Workout</label><input name="workout"></div><div><label>Weight kg</label><input name="weight" step=".1"></div></div><label>Notes</label><textarea name="notes"></textarea><button>Save Activity</button></form><br><table class="table"><tr><th>Date</th><th>Steps</th><th>Workout</th><th>Calories</th><th>Weight</th><th>Notes</th></tr><?php while($r=mysqli_fetch_assoc($rows)):?><tr><td><?=$r['log_date']?></td><td><?=$r['steps']?></td><td><?=e($r['workout'])?></td><td><?=$r['calories_burned']?></td><td><?=$r['weight_kg']?></td><td><?=e($r['notes'])?></td></tr><?php endwhile;?></table></main></div></body></html>
